flags.typeql:
with fun latest_article_date($o: organization) -> datetime:
  match
    mentions (article: $a, mentioned: $o);
    $a has date $d;
  return max($d);
match
  $o isa organization;
  let $max_date = latest_article_date($o);
  mentions (article: $a, mentioned: $o);
  $a has date $d;
  $d == $max_date;
  $a has sentiment $s;
  $s > 0.8;
fetch {
  "organization_name": $o.name,
  "sentiment_score": $s,
  "article_date": $d
};

match
$p isa person, has name "Julie Spellman Sweet";
parent_of (parent: $parent, child: $p);
$parent has name $n;
limit 3;
fetch {
  "ParentName": $n
};

match
$a isa article;
$city isa city, has city_name $cn;
mentions (article: $a, mentioned: $city);
reduce $count = count($a) groupby $city, $cn;
sort $count desc;
limit 3;
fetch {
  "city_name": $cn,
  "articleCount": $count
};

match
$o isa organization, has founding-date $fd;
$fd < 1975-01-01;
mentions (article: $a, mentioned: $o);
$a has title $t, has date $d, has sentiment $s;
sort $d desc;
limit 3;
fetch {
  "title": $t,
  "date": $d,
  "sentiment": $s
};

match
$org isa organization, has name $org_name;
$sub isa organization;
$city isa city, has city_name $city_name;
subsidiary_of (parent: $org, subsidiary: $sub);
located_in (organization: $org, city: $city);
located_in (organization: $sub, city: $city);
limit 5;
fetch {
  "Organization": $org_name,
  "City": $city_name
};

match
$a isa article, has sentiment $s;
$o isa organization;
mentions (article: $a, mentioned: $o);
reduce $avgSentiment = mean($s) groupby $o;
match $avgSentiment < 0;
sort $avgSentiment asc;
limit 10;
fetch { "organizationName": $o.name, "avgSentiment": $avgSentiment };

flags.cypher:
MATCH (o:Organization)
WHERE EXISTS {
    MATCH (o)-[:HAS_INVESTOR]->(:Person)
    UNION
    MATCH (o)-[:HAS_INVESTOR]->(:Organization)
}
AND NOT EXISTS {
    MATCH (o)-[:HAS_SUBSIDIARY]->(:Organization)
}
RETURN o.name

flags.typeql:
match
$o isa organization;
invested_in (organization: $o);
not { subsidiary_of (parent: $o); };
fetch {
  "name": $o.name
};

match
$o isa organization;
supplies (customer: $o);
limit 3;
fetch { "name": $o.name };

with fun orgs_with_higher_revenue($org: organization) -> integer:
  match
    $org has revenue $rev;
    $other isa organization, has revenue $other_rev;
    $other_rev > $rev;
  return count;
match
$o isa organization, has name $org_name;
let $rank = orgs_with_higher_revenue($o);
$rank < 5;
board_member_of (organization: $o, member: $p);
$p has name $member_name;
fetch {
  "Organization": $org_name,
  "BoardMember": $member_name
};

match
$parentOrg isa organization, has name "Accenture";
subsidiary_of (parent: $parentOrg, subsidiary: $subOrg);
ceo_of (organization: $subOrg, ceo: $ceo);
limit 3;
fetch {
  "CEO": $ceo.name,
  "Subsidiary": $subOrg.name
};

match
$p isa person, has name $pname;
$c isa person, has name $cname;
$o isa organization, has name $oname;
parent_of (parent: $p, child: $c);
$rel1 isa $t1 ($p, organization: $o);
{ $t1 label ceo_of; } or { $t1 label board_member_of; } or { $t1 label invested_in; };
$rel2 isa $t2 ($c, organization: $o);
{ $t2 label ceo_of; } or { $t2 label board_member_of; } or { $t2 label invested_in; };
limit 3;
fetch {
  "Parent": $pname,
  "Child": $cname,
  "Organization": $oname
};

match
$o isa organization, has nbr_employees $max_emp;
not {
  $o2 isa organization, has nbr_employees $emp2;
  $emp2 > $max_emp;
};
$a isa article, has title $t, has date $d, has author $auth, has article_summary $sum;
